// Program.cs
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllersWithViews();

var app = builder.Build();

app.UseHttpsRedirection();
app.UseStaticFiles();
app.UseRouting();
app.UseAuthorization();

// Area route — must come BEFORE the default route
app.MapControllerRoute(
    name: "areas",
    pattern: "{area:exists}/{controller=Home}/{action=Index}/{id?}");

// Default route for root-level controllers
app.MapControllerRoute(
    name: "default",
    pattern: "{controller=Home}/{action=Index}/{id?}");

app.Run();

// Areas/Admin/Controllers/DashboardController.cs
using Microsoft.AspNetCore.Mvc;

namespace MyFirstApp.Areas.Admin.Controllers;

[Area("Admin")]
public class DashboardController : Controller
{
    public IActionResult Index() => View();
}

[Area("Admin")]
[Authorize(Roles = "Admin")]
public class DashboardController : Controller
{
    // Only users in the "Admin" role can access any action in this controller
    public IActionResult Index() => View();

    public IActionResult Users() => View();
}

// Alternatively, apply to a specific action only
public class ProductsController : Controller
{
    [Authorize(Roles = "Admin")]
    public IActionResult Delete(int id) => View(model: id);

    public IActionResult List() => View(); // accessible to everyone
}
